\set ON_ERROR_STOP on
-- #4452 M1 forms_core: executable PostgreSQL 17 proof, after the full migration replay.
--
-- T-1.1a  SC-1   anon and signed-in cannot read or write the M1 tables directly.
-- T-1.1b  SC-2   a website member can call every admin_form_* write; a growth member gets 42501 on writes and can list.
-- T-1.1c  SC-3   admin_team_set_member(email,'website',...) works for a team manager, is refused for growth;
--                the role areas keep their order with website appended.
-- T-1.1d  SC-4   form_versions, site_page_versions and form_automation_versions are immutable.
-- T-1.1e  SC-5   a stale draft rev raises PT409 and leaves the draft unchanged.
-- T-1.1f  SC-6   publishing makes version n+1, the previous version stays byte-identical, live_version_id moves.
-- T-1.1g  SC-7   a slug change keeps the old slug as history; it is never reusable by another form.
-- T-1.1h  SC-9   a locked field cannot be removed or made optional (22023 locked_field).
-- T-1.9b  SC-8, SC-25  the SQL mirror returns exactly what formsContract.ts returns for 300 answer
--                vectors and every definition vector (the block below is generated by
--                _shared/__tests__/issue_4452_forms_contract_vectors.ts; the Deno parity test fails on drift).
-- T-3.2   SC-27  (SQL half) a replayed idempotency key returns the same submission and adds nothing.
-- T-3.3   SC-28, SC-29, I-4452-FORM-DEDUPE-24H  the same email on the same form within 24 h updates the
--                first row (resubmit_count=1, consent only false->true); after 24 h it is a new row.
-- A1-T-5a A1-SC-12  card switch off (the default): no crm_records row, routing_status lead_only, the lead exists.
-- A1-T-5b A1-SC-13  card on: a hosts record and leads.crm_record_id; a second submit with the same email adds a note, no record.
-- A1-T-5c A1-SC-14  a CRM failure with the card on leaves the submission saved with routing_status failed.
-- ADV     a forged live_version_id from another form is refused.
--
-- FAILS-ON-REVERT: removing the advisory lock or the 24 h SELECT in forms_submit_core fails T-3.3;
-- removing the form_submission_keys lookup fails T-3.2; removing the routing.card.on guard in
-- forms_route_submission fails A1-T-5a; changing any rule in forms_validate_definition /
-- forms_validate_answers fails T-1.9b; dropping the REVOKE on forms fails T-1.1a.
-- MINGLA-INVARIANT: I-4452-FORM-DEDUPE-24H | issue #4452 | one form, one email, 24 h -> one row (T-3.3 here).

CREATE OR REPLACE FUNCTION pg_temp.f_assert(p_ok boolean, p_label text)
RETURNS void LANGUAGE plpgsql AS $a$
BEGIN
  IF NOT COALESCE(p_ok, false) THEN
    RAISE EXCEPTION 'issue #4452 forms core FAIL: %', p_label;
  END IF;
  RAISE NOTICE 'PASS  %', p_label;
END
$a$;

CREATE OR REPLACE FUNCTION pg_temp.f_as(p_user uuid)
RETURNS void LANGUAGE plpgsql AS $a$
BEGIN
  PERFORM set_config('request.jwt.claim.sub', p_user::text, true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p_user, 'role', 'authenticated')::text, true);
END
$a$;

-- The SQLSTATE a statement raises, or 'ok'.
CREATE OR REPLACE FUNCTION pg_temp.f_state(p_sql text)
RETURNS text LANGUAGE plpgsql AS $a$
BEGIN
  EXECUTE p_sql;
  RETURN 'ok';
EXCEPTION WHEN OTHERS THEN
  RETURN SQLSTATE;
END
$a$;

-- A submit as forms-submit sends it.
CREATE OR REPLACE FUNCTION pg_temp.f_submit(p_form uuid, p_email text, p_consent boolean, p_key uuid DEFAULT gen_random_uuid())
RETURNS jsonb LANGUAGE plpgsql AS $a$
DECLARE
  v_creator boolean := EXISTS (SELECT 1 FROM public.forms WHERE id = p_form AND template = 'creators');
  v_host boolean := EXISTS (SELECT 1 FROM public.forms WHERE id = p_form AND audience = 'host');
BEGIN
  RETURN public.forms_submit_core(jsonb_build_object(
    'idempotency_key', p_key, 'form_id', p_form, 'email', lower(btrim(p_email)),
    'answers', jsonb_build_object('name', 'Ada Okafor', 'email', p_email, 'consent', p_consent)
      || CASE WHEN v_creator THEN jsonb_build_object(
           'phone', jsonb_build_object('country', 'NG', 'dial', '+234', 'number', '801 234 5678'),
           'what_do_you_make', 'Both',
           'your_main_social', jsonb_build_object('platform', 'instagram', 'value', '@ada.films'),
           'city', jsonb_build_object('label', 'Lagos, Nigeria', 'city', 'Lagos', 'country', 'NG')) ELSE '{}'::jsonb END
      || CASE WHEN v_host THEN jsonb_build_object(
           'phone', jsonb_build_object('country', 'NG', 'dial', '+234', 'number', '801 234 5678'),
           'venue', 'Ada Events Lagos',
           'icp', 'Events',
           'social', jsonb_build_object('platform', 'instagram', 'value', '@ada.events')) ELSE '{}'::jsonb END,
    'consent_text', 'Send me occasional emails from Mingla. Unsubscribe anytime.',
    'time_zone', 'Africa/Lagos', 'time_zone_source', 'browser', 'page_path', '/creators', 'placement', 'inline',
    'spot_key', 'after-steps', 'utm', jsonb_build_object('source', 'meta', 'campaign', 'creators-lagos-nov'),
    'click_source', 'meta', 'ads_allowed', true));
END
$a$;

-- ═══ T-1.1a: grants ══════════════════════════════════════════════════════════
BEGIN;
DO $t$
DECLARE
  v_t text;
BEGIN
  FOREACH v_t IN ARRAY ARRAY['forms','form_versions','form_page_slugs','form_submissions','form_submission_keys',
                             'forms_submit_attempts','form_owner_rotation'] LOOP
    PERFORM pg_temp.f_assert((SELECT relrowsecurity FROM pg_class WHERE oid = ('public.' || v_t)::regclass), 'T-1.1a RLS on ' || v_t);
    PERFORM pg_temp.f_assert((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = v_t) = 0, 'T-1.1a no policies on ' || v_t);
    PERFORM pg_temp.f_assert(NOT has_table_privilege('anon', 'public.' || v_t, 'SELECT,INSERT,UPDATE,DELETE')
                         AND NOT has_table_privilege('authenticated', 'public.' || v_t, 'SELECT,INSERT,UPDATE,DELETE'),
                             'T-1.1a anon and signed-in cannot touch ' || v_t);
  END LOOP;
  PERFORM pg_temp.f_assert(NOT has_function_privilege('anon', 'public.admin_form_publish(uuid,integer)', 'EXECUTE'), 'T-1.1a anon cannot publish');
  PERFORM pg_temp.f_assert(NOT has_function_privilege('authenticated', 'public.forms_submit_core(jsonb)', 'EXECUTE'), 'T-1.1a signed-in cannot call the submit core');
  PERFORM pg_temp.f_assert(public.admin_team_role_areas('website') = ARRAY['role_home','website'], 'T-1.1c website areas');
  PERFORM pg_temp.f_assert(public.admin_team_role_areas('admin') = ARRAY['admin_console','team_manage','crm','beta_leads','email_drafts','website'], 'T-1.1c admin areas keep their order, website appended');
  PERFORM pg_temp.f_assert(public.admin_team_role_areas('growth') = ARRAY['role_home','crm','beta_leads','email_drafts'], 'T-1.1c growth areas unchanged');
END
$t$;
ROLLBACK;

BEGIN;
SET LOCAL ROLE authenticated;
DO $t$
DECLARE v text := 'none';
BEGIN
  BEGIN PERFORM 1 FROM public.form_submissions; EXCEPTION WHEN insufficient_privilege THEN v := 'denied'; END;
  IF v <> 'denied' THEN RAISE EXCEPTION 'issue #4452 forms core FAIL: T-1.1a signed-in read form_submissions'; END IF;
  RAISE NOTICE 'PASS  T-1.1a a signed-in read of form_submissions is denied';
END
$t$;
RESET ROLE;
ROLLBACK;

