-- END #4452 CONTRACT VECTORS
DO $t$
DECLARE
  v jsonb := current_setting('issue4452.vectors')::jsonb;
  v_x jsonb;
  v_got jsonb;
  v_bad integer := 0;
  v_n integer := 0;
  v_pass integer := 0;
BEGIN
  FOR v_x IN SELECT x FROM jsonb_array_elements(v->'answers') x LOOP
    v_n := v_n + 1;
    v_got := public.forms_validate_answers(v->'def', v_x->'answers', (v->>'today')::date);
    IF v_got IS DISTINCT FROM v_x->'expected' THEN
      v_bad := v_bad + 1;
      RAISE WARNING 'answer vector % differs: sql=% ts=%', v_x->>'i', v_got, v_x->'expected';
    END IF;
    IF (v_got->>'ok')::boolean THEN v_pass := v_pass + 1; END IF;
  END LOOP;
  PERFORM pg_temp.f_assert(v_n = 300, 'T-1.9b 300 answer vectors embedded');
  PERFORM pg_temp.f_assert(v_pass BETWEEN 20 AND 280, 'T-1.9b the vectors cover both pass and fail (' || v_pass || ' pass)');
  PERFORM pg_temp.f_assert(v_bad = 0, 'T-1.9b SC-25 SQL answers == TS answers for every vector');
  v_bad := 0;
  FOR v_x IN SELECT x FROM jsonb_array_elements(v->'definitions') x LOOP
    v_got := public.forms_validate_definition(v_x->'def');
    IF (v_got->'ok') IS DISTINCT FROM (to_jsonb((SELECT count(*) = 0 FROM jsonb_array_elements(v_x->'expected'))))
       OR (SELECT COALESCE(jsonb_agg(e ORDER BY e->>'path', e->>'code'), '[]'::jsonb) FROM jsonb_array_elements(v_got->'errors') e)
          IS DISTINCT FROM
          (SELECT COALESCE(jsonb_agg(e ORDER BY e->>'path', e->>'code'), '[]'::jsonb) FROM jsonb_array_elements(v_x->'expected') e) THEN
      v_bad := v_bad + 1;
      RAISE WARNING 'definition vector "%" differs: sql=% ts=%', v_x->>'name', v_got->'errors', v_x->'expected';
    END IF;
  END LOOP;
  PERFORM pg_temp.f_assert(v_bad = 0, 'T-1.9b SC-8 SQL definition rules == TS definition rules for every vector');
  PERFORM pg_temp.f_assert((public.forms_validate_definition(public.forms_default_definition('creator','creators'))->>'ok')::boolean,
    'T-1.9b SC-8 the design''s Creators form is accepted');
END
$t$;
ROLLBACK;

-- ═══ The main flow ═══════════════════════════════════════════════════════════
BEGIN;
ALTER TABLE auth.users ADD COLUMN IF NOT EXISTS email_confirmed_at timestamptz;
DO $main$
DECLARE
  v_admin   constant uuid := '44520000-0000-4000-a000-000000000001';
  v_web     constant uuid := '44520000-0000-4000-a000-000000000002';
  v_growth  constant uuid := '44520000-0000-4000-a000-000000000003';
  v_out     constant uuid := '44520000-0000-4000-a000-000000000004';
  v_form uuid; v_form2 uuid; v_host uuid;
  v jsonb; v_rev integer; v_draft jsonb; v_v1 jsonb; v_sha1 text; v_state text;
  v_s1 jsonb; v_s2 jsonb; v_s3 jsonb; v_key uuid := gen_random_uuid(); v_n bigint; v_sub uuid;
BEGIN
  INSERT INTO auth.users(id, email, email_confirmed_at) VALUES
    (v_admin, 'f4452-admin@mingla-fixture.org', now()), (v_web, 'f4452-web@mingla-fixture.org', now()),
    (v_growth, 'f4452-growth@mingla-fixture.org', now()), (v_out, 'f4452-out@mingla-fixture.org', now());
  INSERT INTO public.admin_users(email, role, status) VALUES ('f4452-admin@mingla-fixture.org', 'admin', 'active')
  ON CONFLICT (email) DO UPDATE SET role = EXCLUDED.role, status = EXCLUDED.status;
  INSERT INTO public.admin_team_members(email, role, status, accepted_at) VALUES
    ('f4452-web@mingla-fixture.org', 'website', 'active', now()),
    ('f4452-growth@mingla-fixture.org', 'growth', 'active', now());

  -- ── T-1.1c: the website role through the team RPC ──
  SET LOCAL ROLE authenticated;
  PERFORM pg_temp.f_as(v_admin);
  v := public.admin_team_set_member('f4452-new-web@mingla-fixture.org', 'website', 'invited');
  PERFORM pg_temp.f_assert(v->>'role' = 'website' AND v->>'status' = 'invited', 'T-1.1c SC-3 a team manager invites a website editor');
  PERFORM pg_temp.f_as(v_growth);
  v_state := pg_temp.f_state($$SELECT public.admin_team_set_member('f4452-other@mingla-fixture.org', 'website', 'invited')$$);
  PERFORM pg_temp.f_assert(v_state = '42501', 'T-1.1c SC-3 a growth member is refused');
  PERFORM pg_temp.f_as(v_web);
  v_state := pg_temp.f_state($$SELECT public.admin_team_set_member('f4452-other@mingla-fixture.org', 'growth', 'invited')$$);
  PERFORM pg_temp.f_assert(v_state = '42501', 'T-1.1c a website editor cannot manage the team');
  PERFORM pg_temp.f_assert(public.forms_can_edit() AND public.forms_can_view(), 'T-1.1b the website editor can edit and view');

  -- ── T-1.1b: writes as the website editor ──
  v := public.admin_form_create('Creators: join the program', 'creator', 'creators');
  v_form := (v->>'id')::uuid;
  PERFORM pg_temp.f_assert(v->>'key' = 'creators-join-the-program', 'T-1.1b create slugifies the key');
  v := public.admin_form_create('Creators: join the program', 'creator', 'creators');
  PERFORM pg_temp.f_assert(v->>'key' = 'creators-join-the-program-2', 'T-1.1b a second form gets a -2 key');
  v_form2 := (v->>'id')::uuid;
  v := public.admin_form_get(v_form);
  v_rev := (v->>'draft_rev')::integer;
  v_draft := v->'draft';
  PERFORM pg_temp.f_assert(jsonb_array_length(v_draft->'fields') = 7, 'T-1.1b the Creators template has its 7 fields');
  PERFORM pg_temp.f_assert(v_draft->'routing'->'card'->'on' = 'false'::jsonb, 'A1-SC-12 the card switch is off by default');

  -- ── T-1.1e: stale rev ──
  v := public.admin_form_save_draft(v_form, v_rev, jsonb_set(v_draft, '{own_page}', '{"on":true,"slug":"creators","index":false,"bg":"night"}'));
  v_state := pg_temp.f_state(format($$SELECT public.admin_form_save_draft(%L, %s, %L::jsonb)$$, v_form, v_rev,
                               jsonb_set(v_draft, '{ads,goal}', '"none"')));
  PERFORM pg_temp.f_assert(v_state = 'PT409', 'T-1.1e SC-5 a stale rev raises PT409');
  RESET ROLE;
  PERFORM pg_temp.f_assert((SELECT draft->'ads'->>'goal' FROM public.forms WHERE id = v_form) = 'call_booked', 'T-1.1e SC-5 the draft is unchanged');
  SET LOCAL ROLE authenticated;
  v_rev := v_rev + 1;

  -- ── T-1.1h: locked fields ──
  v_state := pg_temp.f_state(format($$SELECT public.admin_form_save_draft(%L, %s, %L::jsonb)$$, v_form, v_rev,
                               jsonb_set(v_draft, '{fields}', (v_draft->'fields') - 2)));
  PERFORM pg_temp.f_assert(v_state = '22023', 'T-1.1h SC-9 removing the locked phone is refused');
  v_state := pg_temp.f_state(format($$SELECT public.admin_form_save_draft(%L, %s, %L::jsonb)$$, v_form, v_rev,
                               jsonb_set(jsonb_set(v_draft, '{fields,2,required}', 'false'), '{fields,2,locked}', 'false')));
  PERFORM pg_temp.f_assert(v_state = '22023', 'T-1.1h SC-9 making the locked phone optional is refused');

  -- ── Publish needs the test send (publish check 5) when the flow emails the person ──
  -- (#4452 B22: a form whose flow sends no email passes check 5; issue_4452_flow_validator proves that side.)
  PERFORM public.admin_automation_save_draft(v_form, 0,
    '{"v":1,"steps":[{"id":"e1","type":"email","name":"Welcome","to":"person","from":"creators","reply_to":"team","subject":"Thanks","doc":[{"id":"e1b","type":"rich_text","html":"<p>Thanks.</p>"}],"show_answers":false}]}',
    '{}');
  v_state := pg_temp.f_state(format($$SELECT public.admin_form_publish(%L, %s)$$, v_form, v_rev));
  PERFORM pg_temp.f_assert(v_state = '22023', 'T-1.1f publish is blocked until a test was sent');
  PERFORM public.admin_form_mark_tested(v_form);
  v := public.admin_form_publish(v_form, v_rev);
  PERFORM pg_temp.f_assert((v->>'version')::integer = 1 AND v->>'slug' = 'creators', 'T-1.1f version 1 with its own page');
  RESET ROLE;
  SELECT to_jsonb(fv) - 'published_at', fv.definition_sha256 INTO v_v1, v_sha1 FROM public.form_versions fv WHERE fv.form_id = v_form AND fv.version = 1;
  SET LOCAL ROLE authenticated;
  v := public.admin_form_save_draft(v_form, v_rev, jsonb_set(v_draft, '{own_page}', '{"on":true,"slug":"creators-apply","index":false,"bg":"moss"}'));
  v_rev := (v->>'draft_rev')::integer;
  v := public.admin_form_publish(v_form, v_rev);
  PERFORM pg_temp.f_assert((v->>'version')::integer = 2, 'T-1.1f SC-6 publishing again makes version 2');
  RESET ROLE;
  PERFORM pg_temp.f_assert((SELECT to_jsonb(fv) - 'published_at' FROM public.form_versions fv WHERE fv.form_id = v_form AND fv.version = 1) = v_v1,
    'T-1.1f SC-6 version 1 is byte-identical');
  PERFORM pg_temp.f_assert((SELECT fv.version FROM public.forms f JOIN public.form_versions fv ON fv.id = f.live_version_id WHERE f.id = v_form) = 2,
    'T-1.1f SC-6 live_version_id points to version 2');

  -- ── T-1.1g: slugs ──
  PERFORM pg_temp.f_assert((SELECT is_current FROM public.form_page_slugs WHERE slug = 'creators') = false
                       AND (SELECT is_current FROM public.form_page_slugs WHERE slug = 'creators-apply'), 'T-1.1g SC-7 A is history, B is current');
  SET LOCAL ROLE authenticated;
  v := public.admin_form_get(v_form2);
  v_state := pg_temp.f_state(format($$SELECT public.admin_form_save_draft(%L, %s, %L::jsonb)$$, v_form2, (v->>'draft_rev')::integer,
                               jsonb_set(v->'draft', '{own_page}', '{"on":true,"slug":"creators"}')));
  PERFORM pg_temp.f_assert(v_state = '22023', 'T-1.1g SC-7 another form cannot take the retired slug');
  v_state := pg_temp.f_state(format($$SELECT public.admin_form_save_draft(%L, %s, %L::jsonb)$$, v_form2, (v->>'draft_rev')::integer,
                               jsonb_set(v->'draft', '{own_page}', '{"on":true,"slug":"booked"}')));
  PERFORM pg_temp.f_assert(v_state = '22023', 'T-1.1g a reserved slug is refused');

  -- ── T-1.1b: growth is read-only ──
  PERFORM pg_temp.f_as(v_growth);
  PERFORM pg_temp.f_assert(jsonb_array_length(public.admin_forms_list()->'rows') >= 2, 'T-1.1b SC-2 growth lists forms');
  PERFORM pg_temp.f_assert(pg_temp.f_state(format($$SELECT public.admin_form_create('Nope', 'host')$$)) = '42501', 'T-1.1b SC-2 growth cannot create');
  PERFORM pg_temp.f_assert(pg_temp.f_state(format($$SELECT public.admin_form_save_draft(%L, 1, '{}'::jsonb)$$, v_form2)) = '42501', 'T-1.1b SC-2 growth cannot save');
  PERFORM pg_temp.f_assert(pg_temp.f_state(format($$SELECT public.admin_form_publish(%L, 1)$$, v_form2)) = '42501', 'T-1.1b SC-2 growth cannot publish');
  PERFORM pg_temp.f_assert(pg_temp.f_state(format($$SELECT public.admin_form_archive(%L)$$, v_form2)) = '42501', 'T-1.1b SC-2 growth cannot archive');
  PERFORM pg_temp.f_assert(pg_temp.f_state(format($$SELECT public.admin_form_duplicate(%L)$$, v_form2)) = '42501', 'T-1.1b SC-2 growth cannot duplicate');
  PERFORM pg_temp.f_as(v_out);
  PERFORM pg_temp.f_assert(pg_temp.f_state($$SELECT public.admin_forms_list()$$) = '42501', 'T-1.1b an outsider cannot list');
  RESET ROLE;

  -- ── T-1.1d: immutable versions ──
  PERFORM pg_temp.f_assert(pg_temp.f_state(format($$UPDATE public.form_versions SET definition = '{}' WHERE form_id = %L$$, v_form)) = '42501',
    'T-1.1d SC-4 a form version cannot be updated');
  PERFORM pg_temp.f_assert(pg_temp.f_state(format($$DELETE FROM public.form_versions WHERE form_id = %L$$, v_form)) = '42501',
    'T-1.1d SC-4 a form version cannot be deleted');
  -- ADV: a live version from another form is refused.
  PERFORM pg_temp.f_assert(pg_temp.f_state(format($$UPDATE public.forms SET live_version_id = (SELECT id FROM public.form_versions WHERE form_id = %L LIMIT 1) WHERE id = %L$$, v_form, v_form2)) <> 'ok',
    'ADV a forged live_version_id from another form is refused');

  -- ── T-3.2 / T-3.3: the submit core ──
  SET LOCAL ROLE service_role;
  v_s1 := pg_temp.f_submit(v_form, 'Ada@Mingla-Fixture.org', false, v_key);
  v_s2 := pg_temp.f_submit(v_form, 'Ada@Mingla-Fixture.org', false, v_key);
  PERFORM pg_temp.f_assert((v_s2->>'replay')::boolean AND v_s2->>'submission_id' = v_s1->>'submission_id', 'T-3.2 SC-27 a replayed key returns the same submission');
  v_s3 := pg_temp.f_submit(v_form, 'ada@mingla-fixture.org', true);
  PERFORM pg_temp.f_assert((v_s3->>'deduped')::boolean AND v_s3->>'submission_id' = v_s1->>'submission_id', 'T-3.3 SC-28 the same email within 24 h is deduped onto the first row');
  SELECT count(*) INTO v_n FROM public.form_submissions WHERE form_id = v_form;
  PERFORM pg_temp.f_assert(v_n = 1, 'T-3.3 SC-28 still one row');
  PERFORM pg_temp.f_assert((SELECT resubmit_count = 1 AND marketing_consent FROM public.form_submissions WHERE form_id = v_form),
    'T-3.3 SC-28 resubmit_count 1 and consent went false -> true');
  v_s3 := pg_temp.f_submit(v_form, 'ada@mingla-fixture.org', false);
  PERFORM pg_temp.f_assert((SELECT marketing_consent FROM public.form_submissions WHERE form_id = v_form), 'T-3.3 consent never goes true -> false');
  -- the resubmission's key now replays too
  PERFORM pg_temp.f_assert((pg_temp.f_submit(v_form, 'ada@mingla-fixture.org', false, (SELECT idempotency_key FROM public.form_submission_keys LIMIT 1))->>'replay')::boolean,
    'T-3.2 a resubmission key replays through form_submission_keys');
  RESET ROLE;
  UPDATE public.form_submissions SET created_at = now() - interval '25 hours' WHERE form_id = v_form;
  SET LOCAL ROLE service_role;
  v_s3 := pg_temp.f_submit(v_form, 'ada@mingla-fixture.org', false);
  PERFORM pg_temp.f_assert(NOT (v_s3->>'deduped')::boolean, 'T-3.3b SC-29 after 24 h it is a new submission');
  SELECT count(*) INTO v_n FROM public.form_submissions WHERE form_id = v_form;
  PERFORM pg_temp.f_assert(v_n = 2, 'T-3.3b SC-29 two rows');
  RESET ROLE;

  -- ── A1-T-5a: card off ──
  PERFORM pg_temp.f_assert((SELECT bool_and(routing_status = 'lead_only' AND crm_record_id IS NULL) FROM public.form_submissions WHERE form_id = v_form),
    'A1-T-5a A1-SC-12 card off: routing_status lead_only and no record');
  PERFORM pg_temp.f_assert(NOT EXISTS (SELECT 1 FROM public.crm_activity WHERE via = 'form-creators-join-the-program'), 'A1-T-5a A1-SC-12 no crm_records row');
  PERFORM pg_temp.f_assert(EXISTS (SELECT 1 FROM public.leads WHERE email_key = 'ada@mingla-fixture.org' AND 'creator' = ANY (labels)),
    'A1-T-5a A1-SC-12 the person is in Leads with the Creator label');

  -- ── A1-T-5b / 5c: a host form with the card on ──
  SET LOCAL ROLE authenticated;
  PERFORM pg_temp.f_as(v_admin);
  v := public.admin_form_create('Hosts: get started', 'host', NULL);
  v_host := (v->>'id')::uuid;
  v := public.admin_form_get(v_host);
  PERFORM public.admin_form_save_draft(v_host, (v->>'draft_rev')::integer,
    jsonb_set(v->'draft', '{routing}', '{"card":{"on":true,"pipeline":"hosts"},"owner":{"mode":"unassigned"}}'));
  PERFORM public.admin_form_mark_tested(v_host);
  PERFORM public.admin_form_publish(v_host, (v->>'draft_rev')::integer + 1);
  RESET ROLE;
  SET LOCAL ROLE service_role;
  v_s1 := pg_temp.f_submit(v_host, 'host1@mingla-fixture.org', false);
  RESET ROLE;
  SELECT id INTO v_sub FROM public.form_submissions WHERE id = (v_s1->>'submission_id')::uuid;
  PERFORM pg_temp.f_assert((SELECT routing_status = 'routed' AND crm_record_id IS NOT NULL FROM public.form_submissions WHERE id = v_sub),
    'A1-T-5b A1-SC-13 card on: routed with a record');
  PERFORM pg_temp.f_assert((SELECT r.pipeline FROM public.form_submissions s JOIN public.crm_records r ON r.id = s.crm_record_id WHERE s.id = v_sub) = 'hosts',
    'A1-T-5b A1-SC-13 the record is in hosts');
  PERFORM pg_temp.f_assert((SELECT l.crm_record_id = s.crm_record_id AND l.crm_pipeline = 'hosts'
                              FROM public.leads l JOIN public.form_submissions s ON s.email = l.email_key WHERE s.id = v_sub),
    'A1-T-5b A1-SC-13 leads.crm_record_id is set');
  SELECT count(*) INTO v_n FROM public.crm_records;
  -- The same name again (a different email still matches the card by name): a note, not a duplicate.
  SET LOCAL ROLE service_role;
  v_s2 := pg_temp.f_submit(v_host, 'host2@mingla-fixture.org', false);
  RESET ROLE;
  PERFORM pg_temp.f_assert((SELECT count(*) FROM public.crm_records) = v_n,
    'A1-T-5b A1-SC-13 a second submit for the same person adds no record');
  PERFORM pg_temp.f_assert((SELECT routing_status FROM public.form_submissions WHERE id = (v_s2->>'submission_id')::uuid) = 'noted_existing'
                       AND EXISTS (SELECT 1 FROM public.crm_activity a JOIN public.form_submissions s ON s.crm_record_id = a.record_id
                                    WHERE s.id = (v_s2->>'submission_id')::uuid AND a.kind = 'note' AND a.body LIKE 'Sent the form%'),
    'A1-T-5b A1-SC-13 the existing card gets a note');
  -- A1-T-5c: make the CRM call fail (an owner who is not on the team).
  SET LOCAL ROLE authenticated;
  PERFORM pg_temp.f_as(v_admin);
  v := public.admin_form_get(v_host);
  PERFORM public.admin_form_save_draft(v_host, (v->>'draft_rev')::integer,
    jsonb_set(v->'draft', '{routing}', '{"card":{"on":true,"pipeline":"hosts"},"owner":{"mode":"person","emails":["nobody@mingla-fixture.org"]}}'));
  PERFORM public.admin_form_publish(v_host, (v->>'draft_rev')::integer + 1);
  RESET ROLE;
  SET LOCAL ROLE service_role;
  v_s3 := pg_temp.f_submit(v_host, 'host3@mingla-fixture.org', false);
  RESET ROLE;
  PERFORM pg_temp.f_assert((SELECT routing_status = 'failed' FROM public.form_submissions WHERE id = (v_s3->>'submission_id')::uuid),
    'A1-T-5c A1-SC-14 a CRM failure: the submission is saved with routing_status failed');
  PERFORM pg_temp.f_assert(EXISTS (SELECT 1 FROM public.leads WHERE email_key = 'host3@mingla-fixture.org' AND crm_record_id IS NULL),
    'A1-T-5c A1-SC-14 the lead is in Leads with no card (Add to pipeline)');

  -- Archive closes the form.
  SET LOCAL ROLE authenticated;
  PERFORM pg_temp.f_as(v_web);
  PERFORM public.admin_form_archive(v_form);
  RESET ROLE;
  SET LOCAL ROLE service_role;
  PERFORM pg_temp.f_assert(pg_temp.f_state(format($$SELECT pg_temp.f_submit(%L, 'z@mingla-fixture.org', false)$$, v_form)) = '22023',
    'T-3.7 SC-33 (SQL half) an archived form refuses submits');
  RESET ROLE;
  PERFORM pg_temp.f_assert(NOT EXISTS (SELECT 1 FROM public.form_page_slugs WHERE form_id = v_form AND is_current), 'archive retires the own page');
END
$main$;
ROLLBACK;
